from math import hypot

def find_islands(items, margin):
    """
    Return all items that have no neighbors within `margin` distance.
    Position is taken from item['transform'][4:6].
    """
    # Precompute positions
    positions = [
        (item['transform'][4], item['transform'][5])
        for item in items
    ]

    islands = []
    n = len(items)

    for i in range(n):
        x_i, y_i = positions[i]
        has_neighbor = False

        for j in range(n):
            if i == j:
                continue
            x_j, y_j = positions[j]

            # Euclidean distance
            if hypot(x_i - x_j, y_i - y_j) <= margin:
                has_neighbor = True
                break

        if not has_neighbor:
            islands.append(items[i])

    return islands

print(find_islands(items,20))